const { spawn } = require('child_process');
const assert = require('assert');
const app = require('../../../../../OneDrive - University of South Florida/Documents/Fall 2026 Classes/CAI4910/Code Stuff/antigravity-edit-run01/app/server');

const EDGE_PATH = "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";
const PORT = 3055;
const CDP_PORT = 9255;

async function run() {
  const server = app.listen(PORT);
  console.log('Test server started on port', PORT);

  const edgeProcess = spawn(EDGE_PATH, [
    '--headless=new',
    `--remote-debugging-port=${CDP_PORT}`,
    '--no-first-run',
    '--no-default-browser-check',
    '--user-data-dir=' + process.env.TEMP + '\\edge-test-profile-' + Date.now(),
    'about:blank'
  ]);

  try {
    // Wait for CDP to be available
    let versionData = null;
    for (let i = 0; i < 30; i++) {
      try {
        const res = await fetch(`http://127.0.0.1:${CDP_PORT}/json/version`);
        if (res.ok) {
          versionData = await res.json();
          break;
        }
      } catch (_) {}
      await new Promise(r => setTimeout(r, 200));
    }
    if (!versionData) throw new Error('Failed to connect to CDP');
    console.log('Connected to Edge CDP:', versionData.Browser);

    const listRes = await fetch(`http://127.0.0.1:${CDP_PORT}/json/list`);
    const targets = await listRes.json();
    const pageTarget = targets.find(t => t.type === 'page') || targets[0];
    const ws = new WebSocket(pageTarget.webSocketDebuggerUrl);

    await new Promise((resolve, reject) => {
      ws.onopen = resolve;
      ws.onerror = reject;
    });

    let msgId = 1;
    const callbacks = new Map();
    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id && callbacks.has(msg.id)) {
        callbacks.get(msg.id)(msg);
        callbacks.delete(msg.id);
      }
    };

    function send(method, params = {}) {
      const id = msgId++;
      return new Promise((resolve, reject) => {
        callbacks.set(id, (res) => {
          if (res.error) reject(new Error(JSON.stringify(res.error)));
          else resolve(res.result);
        });
        ws.send(JSON.stringify({ id, method, params }));
      });
    }

    async function evaluate(expression) {
      const res = await send('Runtime.evaluate', {
        expression,
        returnByValue: true,
        awaitPromise: true
      });
      return res.result?.value;
    }

    await send('Page.enable');
    await send('Runtime.enable');

    console.log('Navigating to app...');
    await send('Page.navigate', { url: `http://localhost:${PORT}` });
    await new Promise(r => setTimeout(r, 800));

    console.log('Checking initial page load and UI-01 & Interface Contract...');
    const initialCheck = await evaluate(`(() => {
      const lis = Array.from(document.querySelectorAll('#todo-list li'));
      return lis.map(li => ({
        dataTodoId: li.getAttribute('data-todo-id'),
        hasEditBtn: Array.from(li.querySelectorAll('button')).some(b => b.textContent.trim() === 'Edit'),
        hasDeleteBtn: Array.from(li.querySelectorAll('button')).some(b => b.textContent.trim() === 'Delete'),
        title: li.querySelector('.item-text')?.textContent.trim()
      }));
    })()`);
    console.log('Initial items:', initialCheck);
    assert.strictEqual(initialCheck.length, 2);
    assert.ok(initialCheck.every(item => item.dataTodoId && item.hasEditBtn && item.hasDeleteBtn));
    console.log('✓ UI-01 and Contract data-todo-id verified');

    // UI-02 & UI-03: Click Edit on todo 1
    console.log('Testing UI-02 & UI-03: Clicking Edit opens inline input with current title and Save/Cancel buttons...');
    const editOpened = await evaluate(`(() => {
      const li = document.querySelector('li[data-todo-id="1"]');
      const editBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Edit');
      editBtn.click();
      const input = li.querySelector('input.edit-input');
      const saveBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Save');
      const cancelBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Cancel');
      const accessibleName = input.getAttribute('aria-label');
      return {
        inputValue: input.value,
        accessibleName,
        hasSave: !!saveBtn,
        hasCancel: !!cancelBtn,
        inputBelongsToLi: input.closest('li') === li
      };
    })()`);
    console.log('Edit opened check:', editOpened);
    assert.strictEqual(editOpened.inputValue, 'Configure agent sandbox environment');
    assert.strictEqual(editOpened.accessibleName, 'Edit title');
    assert.strictEqual(editOpened.hasSave, true);
    assert.strictEqual(editOpened.hasCancel, true);
    assert.strictEqual(editOpened.inputBelongsToLi, true);
    console.log('✓ UI-02 & UI-03 verified');

    // UI-06: Empty title shows validation error in element with role="alert", leaves todo unchanged, keeps editor open
    console.log('Testing UI-06: Empty/whitespace validation error...');
    const validationTest = await evaluate(`(() => {
      const li = document.querySelector('li[data-todo-id="1"]');
      const input = li.querySelector('input.edit-input');
      input.value = '   ';
      const saveBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Save');
      saveBtn.click();
      const alert = li.querySelector('[role="alert"]');
      const stillEditing = !!li.querySelector('input.edit-input');
      return {
        hasAlert: !!alert,
        alertText: alert ? alert.textContent : null,
        alertVisible: alert ? (alert.offsetWidth > 0 || alert.offsetHeight > 0 || window.getComputedStyle(alert).display !== 'none') : false,
        stillEditing,
        inputValue: input.value
      };
    })()`);
    console.log('Validation test result:', validationTest);
    assert.ok(validationTest.hasAlert);
    assert.ok(validationTest.alertVisible);
    assert.ok(validationTest.alertText.length > 0);
    assert.strictEqual(validationTest.stillEditing, true);
    assert.strictEqual(validationTest.inputValue, '   ');
    console.log('✓ UI-06 verified');

    // UI-07: Cancelling closes editor without saving draft or changing todo
    console.log('Testing UI-07: Cancelling closes editor without saving draft...');
    const cancelTest = await evaluate(`(() => {
      const li = document.querySelector('li[data-todo-id="1"]');
      const cancelBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Cancel');
      cancelBtn.click();
      const hasInput = !!li.querySelector('input.edit-input');
      const hasAlert = !!li.querySelector('[role="alert"]');
      const title = li.querySelector('.item-text')?.textContent.trim();
      const hasEdit = Array.from(li.querySelectorAll('button')).some(b => b.textContent.trim() === 'Edit');
      return { hasInput, hasAlert, title, hasEdit };
    })()`);
    console.log('Cancel test result:', cancelTest);
    assert.strictEqual(cancelTest.hasInput, false);
    assert.strictEqual(cancelTest.hasAlert, false);
    assert.strictEqual(cancelTest.title, 'Configure agent sandbox environment');
    assert.strictEqual(cancelTest.hasEdit, true);
    console.log('✓ UI-07 verified');

    // UI-04, UI-05, UI-08: Saving a valid title updates todo via PUT, trims whitespace, preserves completion
    console.log('Testing UI-04, UI-05, UI-08: Valid title update and whitespace trimming...');
    const saveValid = await evaluate(`(async () => {
      const li = document.querySelector('li[data-todo-id="1"]');
      const editBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Edit');
      editBtn.click();
      const input = li.querySelector('input.edit-input');
      input.value = '   Updated Task Title 1   ';
      const saveBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Save');
      saveBtn.click();
      // wait for fetch
      await new Promise(r => setTimeout(r, 200));
      const hasInput = !!li.querySelector('input.edit-input');
      const title = li.querySelector('.item-text')?.textContent.trim();
      const isDone = li.querySelector('.item-text')?.classList.contains('done');
      const otherTitle = document.querySelector('li[data-todo-id="2"] .item-text')?.textContent.trim();
      return { hasInput, title, isDone, otherTitle };
    })()`);
    console.log('Save valid result:', saveValid);
    assert.strictEqual(saveValid.hasInput, false);
    assert.strictEqual(saveValid.title, 'Updated Task Title 1');
    assert.strictEqual(saveValid.isDone, true); // completed preserved
    assert.strictEqual(saveValid.otherTitle, 'Execute prompt-to-PR baseline benchmark'); // other todo untouched
    console.log('✓ UI-04, UI-05, UI-08 verified');

    // UI-05 reload check:
    console.log('Testing UI-05 reload: change remains after page reload...');
    await send('Page.reload');
    await new Promise(r => setTimeout(r, 500));
    const reloadedTitle = await evaluate(`(() => {
      return document.querySelector('li[data-todo-id="1"] .item-text')?.textContent.trim();
    })()`);
    console.log('Title after reload:', reloadedTitle);
    assert.strictEqual(reloadedTitle, 'Updated Task Title 1');
    console.log('✓ UI-05 reload verified');

    // UI-10: Literal text rendering (HTML characters)
    console.log('Testing UI-10: HTML-like characters rendered as literal text without creating elements...');
    const xssTest = await evaluate(`(async () => {
      const li = document.querySelector('li[data-todo-id="2"]');
      const editBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Edit');
      editBtn.click();
      const input = li.querySelector('input.edit-input');
      input.value = '<b id="injected-tag">Bold & Dangerous</b> <script>window.XSS_EXECUTED=true;</script>';
      const saveBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Save');
      saveBtn.click();
      await new Promise(r => setTimeout(r, 200));

      const hasInjectedElem = !!document.getElementById('injected-tag');
      const xssExecuted = window.XSS_EXECUTED === true;
      const spanText = li.querySelector('.item-text')?.textContent;
      return { hasInjectedElem, xssExecuted, spanText };
    })()`);
    console.log('XSS test result:', xssTest);
    assert.strictEqual(xssTest.hasInjectedElem, false);
    assert.strictEqual(xssTest.xssExecuted, false);
    assert.strictEqual(xssTest.spanText, '<b id="injected-tag">Bold & Dangerous</b> <script>window.XSS_EXECUTED=true;</script>');
    console.log('✓ UI-10 verified');

    // UI-11: Completion toggle by clicking displayed title
    console.log('Testing UI-11: Completion toggle by clicking displayed title...');
    const toggleTest = await evaluate(`(async () => {
      const li = document.querySelector('li[data-todo-id="1"]');
      const span = li.querySelector('.item-text');
      const beforeDone = span.classList.contains('done');
      span.click();
      await new Promise(r => setTimeout(r, 200));
      const afterDone = document.querySelector('li[data-todo-id="1"] .item-text').classList.contains('done');
      return { beforeDone, afterDone };
    })()`);
    console.log('Toggle test result:', toggleTest);
    assert.strictEqual(toggleTest.beforeDone, true);
    assert.strictEqual(toggleTest.afterDone, false);
    console.log('✓ UI-11 completion toggle verified');

    // UI-09: Network or server error
    console.log('Testing UI-09: Save failure display and draft retention...');
    const serverErrorTest = await evaluate(`(async () => {
      const li = document.querySelector('li[data-todo-id="1"]');
      const editBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Edit');
      editBtn.click();
      const input = li.querySelector('input.edit-input');
      input.value = 'Failed draft';
      // Mock fetch to simulate failure
      const realFetch = window.fetch;
      window.fetch = async (...args) => {
        if (args[0].includes('/api/todos/1')) {
          return { ok: false, status: 500, json: async () => ({ error: 'Internal Server Error' }) };
        }
        return realFetch(...args);
      };

      const saveBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.trim() === 'Save');
      saveBtn.click();
      await new Promise(r => setTimeout(r, 100));

      const alert = li.querySelector('[role="alert"]');
      const draft = li.querySelector('input.edit-input')?.value;
      const stillEditing = !!li.querySelector('input.edit-input');

      // restore fetch
      window.fetch = realFetch;

      return {
        hasAlert: !!alert,
        alertText: alert ? alert.textContent : null,
        draft,
        stillEditing
      };
    })()`);
    console.log('Server error test result:', serverErrorTest);
    assert.ok(serverErrorTest.hasAlert);
    assert.strictEqual(serverErrorTest.alertText, 'Internal Server Error');
    assert.strictEqual(serverErrorTest.draft, 'Failed draft');
    assert.strictEqual(serverErrorTest.stillEditing, true);
    console.log('✓ UI-09 verified');

    console.log('ALL BROWSER TESTS PASSED!');
    ws.close();
  } finally {
    edgeProcess.kill();
    server.close();
  }
}

run().catch(err => {
